// speech synthesis
let speechWarningShown = false;
function showSpeechToast(){
  if(speechWarningShown) return;
  speechWarningShown = true;
  const toast = document.createElement('div');
  toast.id = 'speechToast';
  toast.innerHTML = `
    <div class="toast-inner">
      <strong>🔇 La voz no funciono en este navegador/equipo.</strong>
      <p>No es un error del archivo — depende de las voces instaladas en tu sistema. El pinyin de cada
      tarjeta ya te muestra como se pronuncia. Si quieres activar la voz china:</p>
      <ul>
        <li><strong>Windows:</strong> Configuracion → Hora e idioma → Idioma y region → Agregar idioma →
        elige "Chino (simplificado)" y asegurate de instalar el paquete de "texto a voz".</li>
        <li>Tambien puedes probar abriendo este mismo archivo en <strong>Microsoft Edge</strong> en vez
        de Chrome — a veces detecta mejor las voces ya instaladas en Windows.</li>
      </ul>
      <button id="speechToastClose">Entendido</button>
    </div>`;
  document.body.appendChild(toast);
  document.getElementById('speechToastClose').addEventListener('click', ()=>{
    toast.remove();
  });
}

let speechRate = 0.75;
document.getElementById('speedControl').addEventListener('click', (e)=>{
  const btn = e.target.closest('button[data-rate]');
  if(!btn) return;
  document.querySelectorAll('#speedControl button').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  speechRate = parseFloat(btn.getAttribute('data-rate'));
});

function speak(text){
  if(!text) return; // "Jugar de nuevo" buttons reuse .speak-btn for styling but have no data-hz
  const clean = text.replace(/[（(].*?[）)]/g,''); // strip parentheticals just in case
  if(!('speechSynthesis' in window) || typeof SpeechSynthesisUtterance === 'undefined'){
    showSpeechToast();
    return;
  }
  try{
    // Chrome/Edge have a known race condition where calling speak() in the same tick
    // right after cancel() can silently drop or misapply the new utterance's rate.
    // A short delay lets the cancel fully complete before the new (correctly-timed)
    // utterance is queued, so each click reliably plays back at the currently
    // selected speed.
    window.speechSynthesis.cancel();
    setTimeout(()=>{
      try{
        const utter = new SpeechSynthesisUtterance(clean);
        utter.lang = 'zh-CN';
        utter.rate = speechRate;
        utter.pitch = 1;
        utter.volume = 1;
        const voices = window.speechSynthesis.getVoices();
        let zhVoice = null;
        if(selectedVoiceName){
          zhVoice = voices.find(v=>v.name === selectedVoiceName);
        }
        if(!zhVoice){
          zhVoice = voices.find(v=>v.lang && v.lang.toLowerCase().startsWith('zh'));
        }
        if(zhVoice) utter.voice = zhVoice;
        utter.onerror = ()=>{ showSpeechToast(); };
        window.speechSynthesis.speak(utter);
      }catch(e2){
        showSpeechToast();
      }
    }, 60);
  }catch(e){
    showSpeechToast();
  }
}
let selectedVoiceName = null;
function populateVoiceSelect(){
  if(!('speechSynthesis' in window)) return;
  const voices = window.speechSynthesis.getVoices();
  const zhVoices = voices.filter(v => v.lang && v.lang.toLowerCase().startsWith('zh'));
  const wrap = document.getElementById('voiceControlWrap');
  const sel = document.getElementById('voiceSelect');
  if(zhVoices.length === 0){
    wrap.style.display = 'none';
    return;
  }
  sel.innerHTML = zhVoices.map(v =>
    `<option value="${v.name}">${v.name} (${v.lang})</option>`
  ).join('');
  if(zhVoices.length === 1){
    document.querySelector('.voice-hint').textContent =
      'Tu equipo solo tiene una voz china instalada — no hay otra para comparar.';
  }
  if(selectedVoiceName && zhVoices.some(v=>v.name === selectedVoiceName)){
    sel.value = selectedVoiceName;
  }else{
    selectedVoiceName = sel.value;
  }
  wrap.style.display = 'block';
}
if('speechSynthesis' in window){
  window.speechSynthesis.onvoiceschanged = populateVoiceSelect;
  populateVoiceSelect();
}
document.getElementById('voiceSelect').addEventListener('change', (e)=>{
  selectedVoiceName = e.target.value;
});

