const missedIndices = new Set();
let reviewMissedMode = false;
function addMissed(term){
  if(term == null) return;
  missedIndices.add(term.idx);
  updateMissedButton();
}
function removeMissed(term){
  if(term == null) return;
  if(missedIndices.delete(term.idx)) updateMissedButton();
}
function updateMissedButton(){
  const btn = document.getElementById('missedBtn');
  const countEl = document.getElementById('missedCount');
  countEl.textContent = missedIndices.size;
  btn.style.display = missedIndices.size > 0 ? 'inline-block' : 'none';
  btn.classList.toggle('active-review', reviewMissedMode);
}
function renderGlossary(filter=''){
  const f = filter.trim().toLowerCase();
  const list = ALL_TERMS.filter(t=>{
    if(!f) return true;
    return t.h.includes(f) || t.p.toLowerCase().includes(f) || t.e.toLowerCase().includes(f);
  });
  document.getElementById('glossaryList').innerHTML = list.map(t=>{
    const iconSrc = getIconB64(t.sectionKey, t.h);
    const iconHtml = iconSrc
      ? `<img class="app-icon app-icon-sm" src="${iconSrc}" alt="icono ${t.h}">`
      : `<div class="app-icon app-icon-sm app-icon-placeholder">${t.h.slice(0,1)}</div>`;
    return `
    <div class="glossary-row">
      ${iconHtml}
      <span class="tag">${t.section.split('—')[0].trim()}</span>
      <span class="hz">${t.h}${tradBadge(t.t)}</span>
      <span class="py">${t.p}</span>
      <span class="en">${t.e}</span>
      <button class="speak-btn" data-hz="${t.h.replace(/"/g,'&quot;')}">🔊</button>
    </div>
  `;
  }).join('') || '<p style="padding:14px;color:#999;">Sin resultados.</p>';
}
