// ---------------------------------------------------------------
// Match the words game
// ---------------------------------------------------------------
const MATCH_ROUND_SIZE = 6;
let matchPairs = [];
let matchTiles = [];
let matchSelectedId = null;
let matchCorrectCount = 0;
let matchWrongCount = 0;

function startMatchRound(){
  const pool = getPoolIndices(currentLevel);
  if(pool.length === 0){
    document.getElementById('matchGrid').innerHTML = '<p style="text-align:center;color:#999;">No hay suficientes palabras en este filtro.</p>';
    document.getElementById('matchStats').textContent = '';
    return;
  }
  const size = Math.min(MATCH_ROUND_SIZE, pool.length);
  const chosen = shuffle([...pool]).slice(0, size);
  matchPairs = chosen.map(i => ALL_TERMS[i]);
  matchTiles = [];
  matchPairs.forEach((t, pairId)=>{
    matchTiles.push({id:'hz'+pairId, type:'hz', text:t.h, pairId, matched:false, term:t});
    matchTiles.push({id:'en'+pairId, type:'en', text:t.e, pairId, matched:false, term:t});
  });
  matchTiles = shuffle(matchTiles);
  matchSelectedId = null;
  matchCorrectCount = 0;
  matchWrongCount = 0;
  document.getElementById('matchSummary').style.display = 'none';
  document.getElementById('matchGrid').style.display = 'grid';
  renderMatchGrid();
  updateMatchStats();
}

function renderMatchGrid(){
  const grid = document.getElementById('matchGrid');
  grid.innerHTML = matchTiles.map(t => `
    <button class="match-tile ${t.type==='hz' ? 'match-tile-hz' : 'match-tile-en'}" data-id="${t.id}">${t.text}</button>
  `).join('');
}

function updateMatchStats(){
  document.getElementById('matchStats').textContent =
    `Aciertos: ${matchCorrectCount}/${matchPairs.length} · Errores: ${matchWrongCount}`;
}

document.getElementById('matchGrid').addEventListener('click', (e)=>{
  const btn = e.target.closest('.match-tile');
  if(!btn || btn.disabled) return;
  const id = btn.getAttribute('data-id');
  const tile = matchTiles.find(t=>t.id===id);
  if(tile.matched) return;

  if(!matchSelectedId){
    matchSelectedId = id;
    btn.classList.add('selected');
    return;
  }
  if(matchSelectedId === id){
    btn.classList.remove('selected');
    matchSelectedId = null;
    return;
  }
  const selTile = matchTiles.find(t=>t.id===matchSelectedId);
  const selBtn = document.querySelector(`.match-tile[data-id="${matchSelectedId}"]`);

  if(selTile.type === tile.type){
    selBtn.classList.remove('selected');
    matchSelectedId = id;
    btn.classList.add('selected');
    return;
  }

  if(selTile.pairId === tile.pairId){
    selTile.matched = true;
    tile.matched = true;
    matchCorrectCount++;
    [selBtn, btn].forEach(b=>{
      b.classList.remove('selected');
      b.classList.add('correct');
      b.disabled = true;
    });
    removeMissed(tile.term);
    speak(tile.type === 'hz' ? tile.text : selTile.text);
    matchSelectedId = null;
    updateMatchStats();
    if(matchCorrectCount === matchPairs.length){
      setTimeout(showMatchSummary, 500);
    }
  }else{
    matchWrongCount++;
    addMissed(selTile.term);
    addMissed(tile.term);
    [selBtn, btn].forEach(b=> b.classList.add('wrong-flash'));
    matchSelectedId = null;
    updateMatchStats();
    setTimeout(()=>{
      [selBtn, btn].forEach(b=>{ b.classList.remove('selected','wrong-flash'); });
    }, 650);
  }
});

function showMatchSummary(){
  document.getElementById('matchGrid').style.display = 'none';
  const summary = document.getElementById('matchSummary');
  summary.style.display = 'block';
  summary.innerHTML = `
    <div class="big-score">${matchPairs.length} / ${matchPairs.length}</div>
    <p>Ronda completa con ${matchWrongCount} error(es)</p>
    <button id="matchReplayBtn" class="speak-btn" style="margin-top:8px;">🔁 Jugar de nuevo</button>
  `;
  document.getElementById('matchReplayBtn').addEventListener('click', startMatchRound);
}

// ---------------------------------------------------------------
// Tone recognition game
// ---------------------------------------------------------------
const TONES_ROUND_SIZE = 12;
let tonesQueue = [];
let tonesQIndex = 0;
let tonesScore = 0;
let tonesStreak = 0;
let tonesAnswered = false;

function populateSectionSelect(){
  const sel = document.getElementById('sectionSelect');
  const counts = {};
  ALL_TERMS.forEach(t=>{
    counts[t.sectionKey] = (counts[t.sectionKey]||0) + 1;
  });
  let optsHtml = `<option value="ALL">🔀 Todas las secciones (${ALL_TERMS.length})</option>`;
  Object.keys(VOCAB.data).forEach(sec=>{
    if(counts[sec] > 0){
      optsHtml += `<option value="${sec}">${VOCAB.titles[sec]} (${counts[sec]})</option>`;
    }
  });
  sel.innerHTML = optsHtml;
}

function getTonesPoolIndices(){
  if(reviewMissedMode){
    let idxs = Array.from(missedIndices).filter(i => TONE_GAME_DATA[ALL_TERMS[i].h]);
    if(simplifiedOnly) idxs = idxs.filter(i => ALL_TERMS[i].t !== 'trad');
    return idxs;
  }
  const sections = resolveSections(currentLevel);
  const idxs = [];
  ALL_TERMS.forEach((t,i)=>{
    if(!TONE_GAME_DATA[t.h]) return;
    if(sections && !sections.includes(t.sectionKey)) return;
    if(simplifiedOnly && t.t === 'trad') return;
    idxs.push(i);
  });
  return idxs;
}

function startTonesRound(){
  const pool = getTonesPoolIndices();
  const size = Math.min(TONES_ROUND_SIZE, pool.length);
  tonesQueue = shuffle([...pool]).slice(0, size);
  tonesQIndex = 0;
  tonesScore = 0;
  tonesStreak = 0;
  document.getElementById('tonesScore').textContent = '0';
  document.getElementById('tonesStreak').textContent = '0';
  document.getElementById('tonesSummary').style.display = 'none';
  document.getElementById('tonesMode').querySelector('.game-question').style.display = '';
  document.getElementById('tonesMode').querySelector('.game-instruction').style.display = '';
  document.getElementById('tonesOptions').style.display = '';
  document.getElementById('tonesNextBtn').style.display = 'none';
  if(tonesQueue.length === 0){
    document.getElementById('tonesOptions').innerHTML =
      '<p style="text-align:center;color:#999;grid-column:1/-1;">No hay suficientes palabras en esta seccion/filtro.</p>';
    document.getElementById('tonesMode').querySelector('.game-question').style.display = 'none';
    document.getElementById('tonesMode').querySelector('.game-instruction').style.display = 'none';
    return;
  }
  showTonesQuestion();
}

function showTonesQuestion(){
  tonesAnswered = false;
  document.getElementById('tonesNextBtn').style.display = 'none';
  document.getElementById('tonesFeedback').textContent = '';
  document.getElementById('tonesFeedback').className = 'game-feedback';

  const term = ALL_TERMS[tonesQueue[tonesQIndex]];
  const data = TONE_GAME_DATA[term.h];
  document.getElementById('tonesHz').innerHTML = term.h + tradBadge(term.t);
  document.getElementById('tonesHz').setAttribute('data-hz', term.h);
  document.getElementById('tonesEn').textContent = term.e;
  document.getElementById('tonesProgress').textContent = `Pregunta ${tonesQIndex+1} de ${tonesQueue.length}`;
  const iconSrc = getIconB64(term.sectionKey, term.h);
  document.getElementById('tonesIconWrap').innerHTML = iconSrc
    ? `<img class="app-icon" style="margin:0 auto 8px;" src="${iconSrc}" alt="icono">`
    : '';

  const options = shuffle([
    {py: data.correct, correct:true},
    ...data.distractors.map(d=>({py:d, correct:false}))
  ]);
  document.getElementById('tonesOptions').innerHTML = options.map(o=>`
    <button class="option-btn" data-correct="${o.correct}">${o.py}</button>
  `).join('');
}

document.getElementById('tonesOptions').addEventListener('click', (e)=>{
  const btn = e.target.closest('.option-btn');
  if(!btn || tonesAnswered) return;
  tonesAnswered = true;
  const isCorrect = btn.getAttribute('data-correct') === 'true';
  const allBtns = document.querySelectorAll('#tonesOptions .option-btn');
  allBtns.forEach(b=>{
    b.disabled = true;
    if(b.getAttribute('data-correct') === 'true') b.classList.add('correct');
  });
  const term = ALL_TERMS[tonesQueue[tonesQIndex]];
  const feedback = document.getElementById('tonesFeedback');
  if(isCorrect){
    tonesScore++;
    tonesStreak++;
    feedback.textContent = '¡Correcto! 🎉';
    feedback.className = 'game-feedback correct-txt';
    removeMissed(term);
  }else{
    btn.classList.add('incorrect');
    tonesStreak = 0;
    feedback.textContent = 'Ese tono no es — mira la opcion correcta en verde';
    feedback.className = 'game-feedback incorrect-txt';
    addMissed(term);
  }
  document.getElementById('tonesScore').textContent = tonesScore;
  document.getElementById('tonesStreak').textContent = tonesStreak;
  document.getElementById('tonesNextBtn').style.display = 'inline-block';
  speak(term.h);
});

document.getElementById('tonesNextBtn').addEventListener('click', ()=>{
  tonesQIndex++;
  if(tonesQIndex >= tonesQueue.length){
    showTonesSummary();
  }else{
    showTonesQuestion();
  }
});

function showTonesSummary(){
  document.getElementById('tonesMode').querySelector('.game-question').style.display = 'none';
  document.getElementById('tonesMode').querySelector('.game-instruction').style.display = 'none';
  document.getElementById('tonesOptions').style.display = 'none';
  document.getElementById('tonesNextBtn').style.display = 'none';
  document.getElementById('tonesFeedback').textContent = '';
  const pct = Math.round((tonesScore / tonesQueue.length) * 100);
  const summary = document.getElementById('tonesSummary');
  summary.style.display = 'block';
  summary.innerHTML = `
    <div class="big-score">${tonesScore} / ${tonesQueue.length}</div>
    <p>${pct}% de tonos correctos en esta ronda</p>
    <button id="tonesReplayBtn" class="speak-btn" style="margin-top:8px;">🔁 Jugar de nuevo</button>
  `;
  document.getElementById('tonesReplayBtn').addEventListener('click', startTonesRound);
}

document.getElementById('tonesSpeak').addEventListener('click', ()=>{
  speak(document.getElementById('tonesHz').getAttribute('data-hz'));
});

// ---------------------------------------------------------------
// Handwriting / stroke-order practice (HanziWriter, data in hanzi-data.js)
// ---------------------------------------------------------------
const WRITE_ROUND_SIZE = 12;
let writeQueue = [];
let writeQIndex = 0;
let writeChars = [];
let writeCharIndex = 0;
let writeWordMistakes = 0;
let writeTotalMistakes = 0;
let writeWriter = null;

function hanziCharDataLoader(char, onLoad, onError){
  const data = HANZI_STROKE_DATA[char];
  if(data) onLoad(data);
  else onError('sin datos de trazos para ' + char);
}

function ensureWriteWriter(){
  if(writeWriter) return writeWriter;
  writeWriter = HanziWriter.create('writeTarget', '一', {
    width: 260,
    height: 260,
    padding: 14,
    showCharacter: false,
    showOutline: true,
    strokeAnimationSpeed: 1,
    delayBetweenStrokes: 200,
    highlightColor: '#2f6fed',
    drawingColor: '#222',
    charDataLoader: hanziCharDataLoader,
  });
  return writeWriter;
}

function hasWritableChar(hz){
  return [...hz].some(ch => HANZI_STROKE_DATA[ch]);
}

function setWriteUiState(state){
  const show = (id, on) => { document.getElementById(id).style.display = on ? '' : 'none'; };
  show('writeQuestion', state === 'active');
  show('writeCharProgress', state === 'active');
  show('writeTarget', state === 'active');
  show('writeControls', state === 'active');
  show('writeNextBtn', false);
  show('writeNoWords', state === 'empty');
  document.getElementById('writeSummary').style.display = state === 'summary' ? 'block' : 'none';
}

function startWriteRound(){
  const pool = reviewMissedMode
    ? Array.from(missedIndices).filter(i => hasWritableChar(ALL_TERMS[i].h) && (!simplifiedOnly || ALL_TERMS[i].t !== 'trad'))
    : getPoolIndices(currentLevel).filter(i => hasWritableChar(ALL_TERMS[i].h));
  const size = Math.min(WRITE_ROUND_SIZE, pool.length);
  writeQueue = shuffle([...pool]).slice(0, size);
  writeQIndex = 0;
  writeTotalMistakes = 0;
  document.getElementById('writeMistakes').textContent = '0';
  if(writeQueue.length === 0){
    setWriteUiState('empty');
    return;
  }
  showWriteWord();
}

function showWriteWord(){
  setWriteUiState('active');
  const term = ALL_TERMS[writeQueue[writeQIndex]];
  writeChars = [...term.h].filter(ch => HANZI_STROKE_DATA[ch]);
  writeCharIndex = 0;
  writeWordMistakes = 0;
  document.getElementById('writePy').innerHTML = term.p + tradBadge(term.t);
  document.getElementById('writeEn').textContent = term.e;
  document.getElementById('writeWordProgress').textContent = `Palabra ${writeQIndex+1} de ${writeQueue.length}`;
  document.getElementById('writeSpeak').setAttribute('data-current', term.h);
  const iconSrc = getIconB64(term.sectionKey, term.h);
  document.getElementById('writeIconWrap').innerHTML = iconSrc
    ? `<img class="app-icon" style="margin:0 auto 8px;" src="${iconSrc}" alt="icono">`
    : '';
  showWriteChar();
}

function quizCurrentChar(){
  writeWriter.quiz({
    showHintAfterMisses: 3,
    onMistake(){
      writeWordMistakes++;
      writeTotalMistakes++;
      document.getElementById('writeMistakes').textContent = writeTotalMistakes;
    },
    onComplete(){
      writeCharIndex++;
      if(writeCharIndex < writeChars.length){
        setTimeout(showWriteChar, 500);
      }else{
        onWriteWordDone();
      }
    },
  });
}

function showWriteChar(){
  const ch = writeChars[writeCharIndex];
  document.getElementById('writeCharProgress').textContent = writeChars.length > 1
    ? `Caracter ${writeCharIndex+1} de ${writeChars.length}: ${ch}`
    : `Caracter: ${ch}`;
  ensureWriteWriter().setCharacter(ch).then(quizCurrentChar);
}

function onWriteWordDone(){
  const term = ALL_TERMS[writeQueue[writeQIndex]];
  if(writeWordMistakes === 0) removeMissed(term);
  else addMissed(term);
  document.getElementById('writeCharProgress').textContent = '¡Palabra completa! ✅';
  document.getElementById('writeNextBtn').style.display = 'inline-block';
}

document.getElementById('writeNextBtn').addEventListener('click', ()=>{
  writeQIndex++;
  if(writeQIndex >= writeQueue.length){
    showWriteSummary();
  }else{
    showWriteWord();
  }
});

function showWriteSummary(){
  setWriteUiState('summary');
  const avg = (writeTotalMistakes / Math.max(1, writeQueue.length)).toFixed(1);
  document.getElementById('writeSummary').innerHTML = `
    <div class="big-score">${writeQueue.length} palabras</div>
    <p>${writeTotalMistakes} trazos con error en total (${avg} por palabra)</p>
    <button id="writeReplayBtn" class="speak-btn" style="margin-top:8px;">🔁 Practicar de nuevo</button>
  `;
  document.getElementById('writeReplayBtn').addEventListener('click', startWriteRound);
}

document.getElementById('writeSpeak').addEventListener('click', ()=>{
  speak(document.getElementById('writeSpeak').getAttribute('data-current'));
});

document.getElementById('writeRedoBtn').addEventListener('click', ()=>{
  if(!writeWriter) return;
  writeWriter.cancelQuiz();
  quizCurrentChar();
});

document.getElementById('writeHintBtn').addEventListener('click', ()=>{
  if(!writeWriter) return;
  writeWriter.cancelQuiz();
  writeWriter.animateCharacter({ onComplete: quizCurrentChar });
});

// init
updateMissedButton();
populateSectionSelect();
resetOrder();
nextCard();
